def token_counts(conditions, facts):
    def bind(pattern, fact):
        if (not isinstance(fact, tuple) or len(pattern) != len(fact)
                or pattern[0] != fact[0]):
            return None
        binds = {}
        for p, f in zip(pattern[1:], fact[1:]):
            if isinstance(p, str) and p.startswith("?"):
                if binds.setdefault(p, f) != f:
                    return None
            elif p != f:
                return None
        return binds

    tokens = [{}]
    counts = [1]
    for pattern in conditions:
        nxt = []
        for binds in tokens:
            for fact in facts:
                extra = bind(pattern, fact)
                if extra is None:
                    continue
                merged, ok = dict(binds), True
                for name, value in extra.items():
                    if merged.setdefault(name, value) != value:
                        ok = False
                        break
                if ok:
                    nxt.append(merged)
        tokens = nxt
        counts.append(len(tokens))
    return counts
